artefacto.contenido:
{
  "kind": "presentation",
  "version": "1.0.0",
  "title": "Pago de siniestros de vida: arquitectura técnica",
  "audience": "technical",
  "theme": "dark",
  "slides": [
    {
      "id": "s1",
      "slideNumber": 1,
      "title": "Arquitectura del pago de siniestros",
      "layout": "sectionDivider",
      "contentBlocks": [
        {
          "type": "text",
          "content": "Parte 1: la solución"
        }
      ],
      "speakerNotes": "Esta sección cubre la vista de contenedores y las integraciones."
    },
    {
      "id": "s2",
      "slideNumber": 2,
      "title": "Vista general de la arquitectura",
      "layout": "architectureOverview",
      "contentBlocks": [
        {
          "type": "diagram",
          "content": {
            "mermaid": "flowchart LR\n  Portal[Portal de siniestros] --> Siniestros[Sistema de siniestros]\n  Siniestros --> Listas[Listas restrictivas]\n  Siniestros --> Tesoreria[Tesorería]",
            "description": "Contenedores principales del pago de siniestros."
          }
        }
      ],
      "speakerNotes": "Señalar que el cruce de listas ocurre antes de cualquier orden de pago."
    },
    {
      "id": "s3",
      "slideNumber": 3,
      "title": "Flujo de liquidación",
      "layout": "diagramFocused",
      "contentBlocks": [
        {
          "type": "diagram",
          "content": {
            "mermaid": "sequenceDiagram\n  participant S as Siniestros\n  participant L as Listas\n  participant T as Tesorería\n  S->>L: Cruce del beneficiario\n  L-->>S: Sin coincidencias\n  S->>T: Orden de pago",
            "description": "Secuencia de liquidación con el control de listas."
          }
        }
      ],
      "speakerNotes": "El control de listas es bloqueante: sin respuesta no hay orden de pago."
    },
    {
      "id": "s4",
      "slideNumber": 4,
      "title": "Antes y después",
      "layout": "twoColumn",
      "contentBlocks": [
        {
          "type": "bullets",
          "content": [
            "Antes: cruce manual de listas",
            "Antes: pagos en lote semanal"
          ]
        },
        {
          "type": "bullets",
          "content": [
            "Después: cruce automático en línea",
            "Después: pago en 48 horas"
          ]
        }
      ],
      "speakerNotes": "Las dos columnas comparan el mismo proceso."
    },
    {
      "id": "s5",
      "slideNumber": 5,
      "title": "Matriz de riesgos técnicos",
      "layout": "riskMatrix",
      "contentBlocks": [
        {
          "type": "table",
          "content": {
            "headers": [
              "Riesgo",
              "Probabilidad",
              "Impacto",
              "Mitigación"
            ],
            "rows": [
              [
                "Caída del servicio de listas",
                "Media",
                "Alto",
                "Cola de reintentos y bloqueo del pago"
              ],
              [
                "Doble pago",
                "Baja",
                "Muy alto",
                "Idempotencia por número de siniestro"
              ],
              [
                "Datos del beneficiario incompletos",
                "Alta",
                "Medio",
                "Validación en el portal"
              ]
            ]
          }
        }
      ],
      "speakerNotes": "El doble pago es el riesgo de mayor impacto y ya tiene control."
    },
    {
      "id": "s6",
      "slideNumber": 6,
      "title": "Hoja de ruta",
      "layout": "roadmap",
      "contentBlocks": [
        {
          "type": "bullets",
          "content": [
            "T1: integración con listas restrictivas",
            "T2: idempotencia de pagos",
            "T3: retiro del lote semanal"
          ]
        },
        {
          "type": "imagePlaceholder",
          "content": "Diagrama de Gantt de la hoja de ruta"
        }
      ],
      "speakerNotes": "La fecha del T3 depende del cierre de auditoría."
    },
    {
      "id": "s7",
      "slideNumber": 7,
      "title": "Hitos del proyecto",
      "layout": "timeline",
      "contentBlocks": [
        {
          "type": "table",
          "content": {
            "headers": [
              "Hito",
              "Fecha",
              "Estado"
            ],
            "rows": [
              [
                "Diseño aprobado",
                "Enero",
                "Completado"
              ],
              [
                "Piloto con un ramo",
                "Abril",
                "En curso"
              ],
              [
                "Despliegue total",
                "Julio",
                "Planificado"
              ]
            ]
          }
        }
      ],
      "speakerNotes": "El piloto usa el ramo de vida individual."
    },
    {
      "id": "s8",
      "slideNumber": 8,
      "title": "Indicadores técnicos",
      "layout": "metricsKpi",
      "contentBlocks": [
        {
          "type": "kpi",
          "content": [
            {
              "label": "Tiempo de liquidación",
              "value": "48 h",
              "trend": "down"
            },
            {
              "label": "Pagos con cruce de listas",
              "value": "100 %",
              "trend": "up"
            }
          ]
        },
        {
          "type": "callout",
          "content": {
            "tone": "risk",
            "title": "Riesgo abierto",
            "body": "La tesorería no expone confirmación en línea todavía."
          }
        }
      ],
      "speakerNotes": "La confirmación en línea es requisito para el despliegue total."
    }
  ]
}
